// Author: abhinavkumarrath #include <bits/stdc++.h>using namespace std; #pragma GCC optimize("O3,unroll-loops")#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt") using ll = long long;using vi = vector<int>;using vll = vector<ll>;using pii = pair<int, int>; #define pb push_back#define all(x) (x).begin(), (x).end()#define sz(x) (int)(x).size()#define fi first#define se second#define rep(i, a, b) for (int i = (a); i < (b); ++i)#define forn(i, n) rep(i, 0, n)#define per(i, a, b) for (int i = (b) - 1; i >= (a); --i)#define rofn(i, n) per(i, 0, n) template<class T> bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }template<class T> bool chmax(T& a, const T& b) { if (a < b) { a = b; return 1; } return 0; } void yes() { cout << "YES\n"; }void no() { cout << "NO\n"; } const int INF = 1e9;const ll LINF = 1e18; const int MAXN = 1000005;bool is_prime[MAXN]; void sieve() {    fill(is_prime, is_prime + MAXN, true);    is_prime[0] = is_prime[1] = false;    for (int i = 2; i * i < MAXN; i++) {        if (is_prime[i]) {            for (int j = i * i; j < MAXN; j += i) {                is_prime[j] = false;            }        }    }} void solve() {    int n;    if (!(cin >> n)) return;        forn(i, n) {        ll x;        cin >> x;                ll root = sqrt(x);        if (root * root == x && is_prime[root]) {            yes();        } else {            no();        }    }} int main() {    ios_base::sync_with_stdio(false);    cin.tie(nullptr);        sieve();        int t = 1;    while (t--) {        solve();    }        return 0;}